<?php $slideImages=$images??[];if(!$slideImages&&!empty($fallback))$slideImages=[['path'=>$fallback]];?>
<?php if($slideImages):?><div class="slideshow" data-slideshow aria-label="<?=t('Фотографии коллекции','Collection photos')?>"><div class="slide-stage"><?php foreach($slideImages as $i=>$image):?><img class="slide<?=$i===0?' active':''?>" src="<?=h($image['path'])?>" alt="<?=h($slideAlt??$pageTitle)?> — <?=$i+1?>" width="1200" height="800" <?=$i===0?'fetchpriority="high"':'loading="lazy"'?> <?=$i?'hidden':''?>><?php endforeach;?></div><?php if(count($slideImages)>1):?><div class="slide-controls"><button type="button" data-prev aria-label="<?=t('Предыдущее фото','Previous photo')?>">←</button><span data-slide-count>01 / <?=str_pad((string)count($slideImages),2,'0',STR_PAD_LEFT)?></span><button type="button" data-next aria-label="<?=t('Следующее фото','Next photo')?>">→</button><button type="button" data-pause aria-label="<?=t('Остановить слайдшоу','Pause slideshow')?>">Ⅱ</button></div><?php endif;?></div><?php endif;?>
